-- Diagnóstico: por que um par apontado pelo Data Quality Monitor (pipeline
-- smartbio) não aparece no TEMP_GEO do critério em banco.
--
-- COMO USAR: rode PRIMEIRO o seu script (o que cria #Geometrias e TEMP_GEO),
-- na MESMA sessão/janela do SSMS, conectada no banco da Ferrari. Depois rode
-- este. #Geometrias é tabela temporária — em outra janela ela não existe.
--
-- Pares: cache/Ferrari.json de 11/11/2026 (419 pares, critério do banco: IDs distintos e > 0,20%).

drop table if exists #ParesPipeline;
drop table if exists #Diag;
create table #ParesPipeline (
  IDTalhao1 int, IDTalhao2 int, AnoSafra1 int, AnoSafra2 int, PctPipeline decimal(10,2)
);

with base as (
  select p.*,
    -- o par está no seu resultado final? (em qualquer ordem)
    case when exists (select 1 from TEMP_GEO t
                      where (t.IDTalhao1 = p.IDTalhao1 and t.IDTalhao2 = p.IDTalhao2)
                         or (t.IDTalhao1 = p.IDTalhao2 and t.IDTalhao2 = p.IDTalhao1))
         then 1 else 0 end as NoSeuResultado,
    (select count(*) from #Geometrias g where g.IDTalhao = p.IDTalhao1) as QtdGeom1,
    (select count(*) from #Geometrias g where g.IDTalhao = p.IDTalhao2) as QtdGeom2,
    (select count(*) from dbo.HistDetalhado h where h.IDTalhao = p.IDTalhao1
        and h.DataInicialSafra <= getdate() and h.DataFinalSafra > getdate() and h.Bloqueio = 0) as HistAtivo1,
    (select count(*) from dbo.HistDetalhado h where h.IDTalhao = p.IDTalhao2
        and h.DataInicialSafra <= getdate() and h.DataFinalSafra > getdate() and h.Bloqueio = 0) as HistAtivo2,
    (select count(*) from dbo.HistDetalhado h join dbo.GeometriaDeMapa gm
        on gm.IDTalhao = h.IDTalhao and gm.IDSafra = h.IDSafra
     where h.IDTalhao = p.IDTalhao1 and h.DataInicialSafra <= getdate()
       and h.DataFinalSafra > getdate() and h.Bloqueio = 0) as GeomSafraAtiva1,
    (select count(*) from dbo.HistDetalhado h join dbo.GeometriaDeMapa gm
        on gm.IDTalhao = h.IDTalhao and gm.IDSafra = h.IDSafra
     where h.IDTalhao = p.IDTalhao2 and h.DataInicialSafra <= getdate()
       and h.DataFinalSafra > getdate() and h.Bloqueio = 0) as GeomSafraAtiva2,
    (select count(*) from dbo.Talhao t join dbo.Fazenda f on f.IDFazenda = t.IDFazenda
     where t.IDTalhao = p.IDTalhao1) as TemTalhaoFazenda1,
    (select count(*) from dbo.Talhao t join dbo.Fazenda f on f.IDFazenda = t.IDFazenda
     where t.IDTalhao = p.IDTalhao2) as TemTalhaoFazenda2
  from #ParesPipeline p
)
select b.*,
  pct.PctNoBanco,
  case
    when b.NoSeuResultado = 1                         then 'OK - aparece nos dois'
    when b.HistAtivo1 = 0 or b.HistAtivo2 = 0         then 'Sem HistDetalhado ativo (data/bloqueio) no banco'
    when b.TemTalhaoFazenda1 = 0 or b.TemTalhaoFazenda2 = 0 then 'Talhão sem vínculo em dbo.Talhao/dbo.Fazenda'
    when b.GeomSafraAtiva1 = 0 or b.GeomSafraAtiva2 = 0 then 'Sem GeometriaDeMapa pra IDSafra ativa (view usa outra fonte)'
    when pct.PctNoBanco is null                       then 'Geometria existe mas não intersecta no banco (geometria diferente da view)'
    when pct.PctNoBanco <= 0.20                       then 'Intersecta, mas abaixo do corte no banco'
    else 'Intersecta acima do corte mas não entrou - checar join/IDTalhao/duplicata'
  end as Diagnostico
into #Diag
from base b
outer apply (
  select max(cast(g1.DadosSHP.STIntersection(g2.DadosSHP).STArea()
         / nullif(g1.DadosSHP.STUnion(g2.DadosSHP).STArea(), 0) * 100 as decimal(10,2))) as PctNoBanco
  from #Geometrias g1 join #Geometrias g2
    on g1.IDTalhao = b.IDTalhao1 and g2.IDTalhao = b.IDTalhao2
  where g1.DadosSHP.STIntersects(g2.DadosSHP) = 1
) pct;

-- 1) Resumo: quantos pares por causa
select Diagnostico, count(*) as Pares
from #Diag
group by Diagnostico
order by Pares desc;

-- 2) Detalhe: só os que faltam no seu resultado
select *
from #Diag
where NoSeuResultado = 0
order by Diagnostico, IDTalhao1;
